		name: "popup1"
	};
	var options = {
		id: "popup1",
		type: "iframePopup",
		width: "400px",
		height: "250px",
		modal: true,
		alwaysOnTop: false,
		dataObj: data
	};
	scwin.$w.openPopup("/sample/common_link/p_popup_modal_false_WEFF-423_(WSQ-3774)_child.xml", options);
};
